use std::path::{Path, PathBuf};

/// Expected source-keyed clone destination, independent of registration lifetime.
#[allow(dead_code)]
pub fn clone_path(root: &Path, source: &Path) -> PathBuf {
    let source = source
        .canonicalize()
        .unwrap_or_else(|_| source.to_path_buf());
    let record = gitpm::Installed {
        source: source.to_string_lossy().into_owned(),
        ..Default::default()
    };
    root.join(record.clone_folder(""))
}

/// Read an identity generated by authoring or fork instead of predicting randomness.
#[allow(dead_code)]
pub fn manifest_id(package: &Path) -> String {
    let manifest: serde_json::Value =
        serde_json::from_slice(&std::fs::read(package.join("plugin.json")).unwrap()).unwrap();
    let id = manifest["id"].as_str().unwrap();
    assert!(gitpm::valid_id(id).is_ok(), "invalid generated UUID: {id}");
    id.to_owned()
}

#[allow(dead_code)]
pub fn package_by_name(repository: &Path, name: &str) -> PathBuf {
    std::fs::read_dir(repository.join("packages"))
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .find(|path| {
            let manifest: serde_json::Value =
                serde_json::from_slice(&std::fs::read(path.join("plugin.json")).unwrap()).unwrap();
            manifest["name"] == name
        })
        .unwrap()
}
